// Collect all reply strings from the aggregate output
const replies = $input.all().map(it => it.json.reply);

// Helper to normalize empty or newline-only values to null
function normalize(value) {
  if (!value) return null; // catches undefined, null, empty string
  const trimmed = String(value).trim();
  return trimmed === "" ? null : trimmed;
}

// Combine them into one message
return {
  reply: replies.join("\n\n"),
  channel_id: $('Aggregate').first().json.channel_id[0],
  isGenerateFile: $('Aggregate').first().json.isGenerateFile[0],
  isTelegram: normalize($('Aggregate').first().json.id[0])
};

const attachmentId = $('HTTP Request6').first().json.result;
const baseUrl = "http://localhost:8069/";  // your Odoo host
const attachmentUrl = `${baseUrl}/web/content/${attachmentId}?download=true`;

return {
  reply: `Here is the file: ${attachmentUrl}`,
  url: attachmentUrl,
};

const raw = $json.reply || "{}";

let data;

try {
  data = JSON.parse(raw);
} catch (e) {
  // If it's not valid JSON, just send raw text safely
  return [
    {
      json: {
        reply: raw
      }
    }
  ];
}

// Extract message safely
return [
  {
    json: {
      reply: data.message || "No message found"
    }
  }
];
